<?php
require_once __DIR__.'/../src/auth.php'; require_role('admin');
$message=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=(string)($_POST['action']??'');
 try {
  if($action==='user_create') {
   $u=trim((string)($_POST['username']??''));$email=trim((string)($_POST['email']??''));$pw=(string)($_POST['password']??'');$role=(string)($_POST['role']??'');
   if(!valid_text($u,60)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8||!in_array($role,['admin','parent','driver'],true)) throw new RuntimeException('Check username, email, password (at least 8 characters) and role.');
   $s=$pdo->prepare('INSERT INTO users(username,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$u,$email,password_hash($pw,PASSWORD_DEFAULT),$role]);$message='User account created.';
  } elseif($action==='bus_save') {
   $id=(int)($_POST['id']??0);$plate=strtoupper(trim((string)($_POST['plate_no']??'')));$driver=trim((string)($_POST['driver_name']??''));$capacity=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT);
   if(!valid_text($plate,30)||!valid_text($driver,120)||$capacity===false||$capacity<1||$capacity>100) throw new RuntimeException('Enter a plate number, driver name and capacity from 1 to 100.');
   if($id){$s=$pdo->prepare('UPDATE buses SET plate_no=?,driver_name=?,capacity=? WHERE bus_id=?');$s->execute([$plate,$driver,$capacity,$id]);$message='Bus updated.';}else{$s=$pdo->prepare('INSERT INTO buses(plate_no,driver_name,capacity) VALUES(?,?,?)');$s->execute([$plate,$driver,$capacity]);$message='Bus added.';}
  } elseif($action==='bus_delete') {$s=$pdo->prepare('DELETE FROM buses WHERE bus_id=?');$s->execute([(int)$_POST['id']]);$message='Bus deleted if it was not assigned to a trip.';
  } elseif($action==='route_save') {
   $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$origin=trim((string)($_POST['origin']??''));$dest=trim((string)($_POST['destination']??''));
   if(!valid_text($name,120)||!valid_text($origin)||!valid_text($dest)) throw new RuntimeException('Complete all route fields.');
   if($id){$s=$pdo->prepare('UPDATE routes SET name=?,origin=?,destination=? WHERE route_id=?');$s->execute([$name,$origin,$dest,$id]);$message='Route updated.';}else{$s=$pdo->prepare('INSERT INTO routes(name,origin,destination) VALUES(?,?,?)');$s->execute([$name,$origin,$dest]);$message='Route added.';}
  } elseif($action==='route_delete') {$s=$pdo->prepare('DELETE FROM routes WHERE route_id=?');$s->execute([(int)$_POST['id']]);$message='Route deleted if it was not assigned to a trip.';
  } elseif($action==='trip_create') {
   $bus=(int)($_POST['bus_id']??0);$route=(int)($_POST['route_id']??0);$start=str_replace('T',' ',(string)($_POST['start_time']??''));$status=(string)($_POST['status']??'scheduled');
   if(!$bus||!$route||!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/',$start)||!in_array($status,['scheduled','active'],true)) throw new RuntimeException('Enter valid trip details.');
   $s=$pdo->prepare('INSERT INTO trips(bus_id,route_id,start_time,status) VALUES(?,?,?,?)');$s->execute([$bus,$route,$start.':00',$status]);$message='Trip created.';
  } elseif($action==='trip_status') {$status=(string)($_POST['status']??'');if(!in_array($status,['scheduled','active','completed','cancelled'],true))throw new RuntimeException('Invalid trip status.');$s=$pdo->prepare('UPDATE trips SET status=?,end_time=IF(?="completed",NOW(),end_time) WHERE trip_id=?');$s->execute([$status,$status,(int)$_POST['id']]);$message='Trip status updated.';}
 } catch(Throwable $ex) { $error=$ex instanceof PDOException?'Could not save. Check for duplicate plate number or a bus/route already used by a trip.':$ex->getMessage(); }
}
$buses=$pdo->query('SELECT * FROM buses ORDER BY bus_id DESC')->fetchAll();$routes=$pdo->query('SELECT * FROM routes ORDER BY route_id DESC')->fetchAll();
$trips=$pdo->query('SELECT t.*,b.plate_no,r.name AS route_name FROM trips t JOIN buses b ON b.bus_id=t.bus_id JOIN routes r ON r.route_id=t.route_id ORDER BY t.trip_id DESC')->fetchAll();
$users=$pdo->query('SELECT user_id,username,email,role,created_at FROM users ORDER BY user_id DESC')->fetchAll();
page_header('Administration');
?>
<h1>Administration</h1><?php if($message):?><div class="success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?>
<div class="grid">
<section class="panel"><h2>Create user</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_create"><label>Username</label><input name="username" maxlength="60" required><label>Email</label><input type="email" name="email" required><label>Temporary password</label><input type="password" name="password" minlength="8" required><label>Role</label><select name="role"><option value="parent">Parent</option><option value="driver">Driver</option><option value="admin">Admin</option></select><button>Create user</button></form></section>
<section class="panel"><h2>Add bus</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="bus_save"><label>Plate number</label><input name="plate_no" maxlength="30" required><label>Driver name</label><input name="driver_name" maxlength="120" required><label>Capacity</label><input type="number" name="capacity" min="1" max="100" required><button>Save bus</button></form></section>
<section class="panel"><h2>Add route</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="route_save"><label>Route name</label><input name="name" maxlength="120" required><label>Origin</label><input name="origin" required><label>Destination</label><input name="destination" required><button>Save route</button></form></section>
<section class="panel"><h2>Create trip</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="trip_create"><label>Bus</label><select name="bus_id" required><?php foreach($buses as $b):?><option value="<?=$b['bus_id']?>"><?=e($b['plate_no'])?></option><?php endforeach;?></select><label>Route</label><select name="route_id" required><?php foreach($routes as $r):?><option value="<?=$r['route_id']?>"><?=e($r['name'])?></option><?php endforeach;?></select><label>Start time</label><input type="datetime-local" name="start_time" required><label>Status</label><select name="status"><option value="scheduled">Scheduled</option><option value="active">Active</option></select><button>Create trip</button></form></section>
</div>
<section class="panel"><h2>Buses (edit/delete)</h2><div class="table-wrap"><table><tr><th>Plate</th><th>Driver</th><th>Capacity</th><th>Actions</th></tr><?php foreach($buses as $b): $formId='bus-update-'.$b['bus_id'];?><tr><td><input form="<?=e($formId)?>" name="plate_no" value="<?=e($b['plate_no'])?>" required></td><td><input form="<?=e($formId)?>" name="driver_name" value="<?=e($b['driver_name'])?>" required></td><td><input form="<?=e($formId)?>" type="number" name="capacity" min="1" max="100" value="<?=$b['capacity']?>" required></td><td><form id="<?=e($formId)?>" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$b['bus_id']?>"><button name="action" value="bus_save">Update</button></form><form method="post" onsubmit="return confirm('Delete this bus?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$b['bus_id']?>"><button class="danger" name="action" value="bus_delete">Delete</button></form></td></tr><?php endforeach;?></table></div></section>
<section class="panel"><h2>Routes (edit/delete)</h2><div class="table-wrap"><table><tr><th>Name</th><th>Origin</th><th>Destination</th><th>Actions</th></tr><?php foreach($routes as $r): $formId='route-update-'.$r['route_id'];?><tr><td><input form="<?=e($formId)?>" name="name" value="<?=e($r['name'])?>" required></td><td><input form="<?=e($formId)?>" name="origin" value="<?=e($r['origin'])?>" required></td><td><input form="<?=e($formId)?>" name="destination" value="<?=e($r['destination'])?>" required></td><td><form id="<?=e($formId)?>" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['route_id']?>"><button name="action" value="route_save">Update</button></form><form method="post" onsubmit="return confirm('Delete this route?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['route_id']?>"><button class="danger" name="action" value="route_delete">Delete</button></form></td></tr><?php endforeach;?></table></div></section>
<section class="panel"><h2>Trips (read/update status)</h2><div class="table-wrap"><table><tr><th>Bus</th><th>Route</th><th>Start</th><th>Status</th><th>Update</th></tr><?php foreach($trips as $t):?><tr><td><?=e($t['plate_no'])?></td><td><?=e($t['route_name'])?></td><td><?=e($t['start_time'])?></td><td><?=e($t['status'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$t['trip_id']?>"><select name="status"><?php foreach(['scheduled','active','completed','cancelled'] as $st):?><option <?=$st===$t['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button name="action" value="trip_status">Save</button></form></td></tr><?php endforeach;?></table></div></section>
<section class="panel"><h2>Users</h2><div class="table-wrap"><table><tr><th>Username</th><th>Email</th><th>Role</th><th>Created</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach;?></table></div></section>
<script src="assets/admin.js"></script><?php page_footer();?>
